#!/usr/bin/env python3
"""Verify portable native include-root snapshots preserve all other generated bytes."""
from __future__ import annotations

import importlib.util
import hashlib
import json
from pathlib import Path
import shutil
import tempfile
import unittest
from unittest.mock import patch

from acceptance_evidence import digest
from corpus_policy import policy_digest, selection_policy

ROOT = Path(__file__).resolve().parents[1]
SPEC = importlib.util.spec_from_file_location("bgcs_corpus_snapshots", ROOT / "scripts/test-corpus.py")
CORPUS = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(CORPUS)

REPORT_SPEC = importlib.util.spec_from_file_location("bgcs_acceptance_report_policy", ROOT / "scripts/write-acceptance-report.py")
REPORT = importlib.util.module_from_spec(REPORT_SPEC)
REPORT_SPEC.loader.exec_module(REPORT)


class CorpusSnapshotTests(unittest.TestCase):
    def setUp(self):
        temporary = ROOT / "artifacts/temporary"
        temporary.mkdir(parents=True, exist_ok=True)
        if not temporary.resolve().is_relative_to(ROOT.resolve()):
            raise RuntimeError("Corpus snapshot test storage escaped the repository.")
        self.temporary = tempfile.TemporaryDirectory(prefix="corpus-snapshot-", dir=temporary)
        self.addCleanup(self.temporary.cleanup)
        self.work = Path(self.temporary.name)

    def source(self, folder: str, body: str = "return 41;"):
        corpus = self.work / folder
        header = corpus / "bimg/include/bimg/bimg.h"
        header.parent.mkdir(parents=True)
        header.write_text("struct Image;\n", encoding="utf-8")
        generated = corpus / "bridge.cpp"
        generated.write_text('#include "' + header.as_posix() + '"\nint read() { ' + body + ' }\n', encoding="utf-8")
        return corpus, generated

    def test_locked_absolute_include_root_is_relocatable_without_file_edits(self):
        first, source = self.source("first checkout")
        second, relocated = self.source("second-路径")
        original = source.read_bytes()
        self.assertNotEqual(digest(source), digest(relocated))
        self.assertEqual(CORPUS.snapshot_source_digest(source, "text/x-c++", first),
                         CORPUS.snapshot_source_digest(relocated, "text/x-c++", second))
        self.assertEqual(original, source.read_bytes())

    def test_native_body_changes_remain_visible(self):
        first, source = self.source("first")
        second, changed = self.source("second", "return 42;")
        self.assertNotEqual(CORPUS.snapshot_source_digest(source, "text/x-c++", first),
                            CORPUS.snapshot_source_digest(changed, "text/x-c++", second))

    def test_unlocked_include_and_ordinary_path_strings_remain_exact(self):
        corpus = self.work / "locked"
        corpus.mkdir()
        external = self.work / "external/header.h"
        source = self.work / "external.cpp"
        source.write_text('#include "' + external.as_posix() + '"\nconst char* path = "' + corpus.as_posix() + '";\n', encoding="utf-8")
        self.assertEqual(digest(source), CORPUS.snapshot_source_digest(source, "text/x-c++", corpus))

    def test_managed_sources_remain_byte_exact(self):
        corpus, source = self.source("managed")
        self.assertEqual(digest(source), CORPUS.snapshot_source_digest(source, "text/x-csharp", corpus))

    def test_reviewed_policy_identity_matches_the_repository_lf_bytes(self):
        # .gitattributes pins repository text to LF. An old CRLF working copy must
        # not produce a reviewed policy identity that fails in a clean checkout.
        policy = (ROOT / "tests/corpus/upstream-limitations.json").read_bytes().replace(b"\r\n", b"\n")
        expected = hashlib.sha256(policy).hexdigest()
        baselines = list((ROOT / "tests/corpus/snapshots").glob("*.windows-x64.json"))
        self.assertEqual(6, len(baselines))
        for path in baselines:
            with self.subTest(library=path.name):
                self.assertEqual(expected, json.loads(path.read_text(encoding="utf-8-sig"))["selectionPolicySha256"])

    def aggregate_policy_fixture(self):
        """Synthetic policy controls stop at the next gate and never create acceptance evidence."""
        root = self.work / "aggregate-policy"
        policy = root / "tests/corpus/upstream-limitations.json"
        policy.parent.mkdir(parents=True)
        lf = (ROOT / "tests/corpus/upstream-limitations.json").read_bytes().replace(b"\r\n", b"\n")
        policy.write_bytes(lf)
        source = {"revision": "a" * 40, "workingTreeDirty": False, "checkedOutSourceSha256": "b" * 64}
        gates, tests, output = root / "gates", root / "test-results", root / "artifacts/acceptance"
        for path in (gates, tests, output, root / "scripts"):
            path.mkdir(parents=True)
        shutil.copyfile(ROOT / "scripts/test-corpus.py", root / "scripts/test-corpus.py")
        (gates / "run-start.json").write_text(json.dumps({"source": source, "startedAtUnixSeconds": 0,
            "usesPrebuiltOutputs": False}), encoding="utf-8")
        for names in REPORT.CATEGORIES.values():
            for name in names:
                (gates / name).touch()
        (tests / "PolicyControl.trx").write_text("synthetic parser input; not executed-test evidence", encoding="utf-8")
        (output / "examples.json").write_text(json.dumps({"success": True,
            "checks": [{"nativeInvoked": True}, {"nativeInvoked": True}]}), encoding="utf-8")
        allocator = {"success": True, "source": source, "sourceBytesStable": True, "nativeBuilt": True,
            "runtimeConsumerInvoked": True, "independentNativeChecksum": True,
            "result": {"checks": 10, "nativeChecksum": 819, "allocator": "example.instance", "nativeReleases": 1, "moduleUnloads": 1},
            "generatedTemporaryAllocatorInvoked": True,
            "generatedTextResult": {"checks": 8, "nativeUtf8ByteLength": 5, "allocator": "example.generated-instance", "nativeReleases": 2, "moduleUnloads": 1}}
        (output / "custom-allocator.json").write_text(json.dumps(allocator), encoding="utf-8")
        for group, libraries in CORPUS.GROUPS.items():
            receipt = {"success": True, "selectedApiPolicy": {"policySha256": hashlib.sha256(lf).hexdigest()},
                "libraries": [{"libraryId": name, "generated": True, "managedCompiled": True, "reviewedSnapshots": True}
                              for name in libraries]}
            (output / ("corpus-" + group + ".json")).write_text(json.dumps(receipt), encoding="utf-8")
        return root, policy, lf, source, gates, tests, output

    def consume_aggregate_policy(self, root, source, gates, tests, output):
        with patch.object(REPORT, "ROOT", root), patch.object(REPORT, "source_identity", return_value=source), \
                patch.object(REPORT, "test_receipt", return_value={"passed": 1}), \
                patch.dict("os.environ", {"GITHUB_ACTIONS": "false"}), \
                patch("sys.argv", ["write-acceptance-report.py", "--gate-root", str(gates), "--test-root", str(tests), "--output", str(output)]):
            REPORT.main()

    def test_aggregate_policy_consumer_accepts_lf_and_crlf_identity_without_certifying_later_gates(self):
        root, policy, lf, source, gates, tests, output = self.aggregate_policy_fixture()
        for raw in (lf, lf.replace(b"\n", b"\r\n")):
            with self.subTest(crlf=b"\r\n" in raw):
                policy.write_bytes(raw)
                # Reaching this unchanged downstream refusal proves both corpus policy receipts passed.
                with self.assertRaisesRegex(RuntimeError, "performance gate did not produce an actual timing receipt"):
                    self.consume_aggregate_policy(root, source, gates, tests, output)
                self.assertEqual(raw, policy.read_bytes())
                self.assertFalse((output / "report.json").exists())

    def test_aggregate_policy_consumer_rejects_a_semantic_change_before_later_gates(self):
        root, policy, lf, source, gates, tests, output = self.aggregate_policy_fixture()
        value = json.loads(lf)
        value["libraries"]["miniaudio"]["reason"] += " Additional source-policy rationale."
        changed = (json.dumps(value, indent=2) + "\n").encode("utf-8")
        self.assertNotEqual(hashlib.sha256(lf).hexdigest(), hashlib.sha256(changed).hexdigest())
        policy.write_bytes(changed)
        with self.assertRaisesRegex(RuntimeError, "current exact source-selection policy"):
            self.consume_aggregate_policy(root, source, gates, tests, output)
        self.assertFalse((output / "report.json").exists())

    def group_report(self, group, status):
        """Simulate producer reports only; these controls never execute a compiler or consumer."""
        lock = CORPUS.load_lock(CORPUS.DEFAULT_LOCK)
        policy_path = ROOT / "tests/corpus/upstream-limitations.json"
        policy = json.loads(policy_path.read_text(encoding="utf-8"))
        repositories = [{**{key: item[key] for key in ("id", "revision", "repository", "checkedOutContentSha256")},
                         "workingTreeClean": True} for item in lock["repositories"]]
        libraries = [{"libraryId": library, "generated": True, "managedCompiled": True, "upstreamInvoked": False,
                      "reviewedSnapshots": status == 0, "success": status == 0, "artifactCount": 4,
                      "omittedDeclarations": policy["libraries"][library]} for library in CORPUS.GROUPS[group]]
        if group == "cpp":
            libraries[0]["nativeBridgeSyntax"] = {"compiler": "fixture-cxx-not-executed", "compilerSha256": "a" * 64,
                "translationUnits": 1, "nativeLinked": False, "upstreamInvoked": False}
        return {"schemaVersion": 1, "scope": CORPUS.REPORT_SCOPE, "group": group, "platform": CORPUS.host_platform(),
                "success": status == 0, "failureKind": "unreviewed-snapshots" if status == 3 else None,
                "upstreamInvoked": False,
                "corpusLockSha256": digest(CORPUS.DEFAULT_LOCK), "repositories": repositories,
                "repositoriesAfter": json.loads(json.dumps(repositories)), "libraries": libraries,
                "selectedApiPolicy": {"schemaVersion": policy["schemaVersion"], "policySha256": policy_digest(policy_path),
                                      "scope": policy["scope"], "libraries": policy["libraries"]},
                "executionIdentity": {"sourceRevision": "b" * 40, "sourceWorktreeDirty": False,
                    **{key: "c" * 64 for key in ("checkedOutSourceSha256", "generatorEntrySha256", "generatorAssemblySha256",
                                                "runtimeAssemblySha256", "executionClosureSha256")}, "executionAssetCount": 5}}

    def collect(self, statuses, mutation=None):
        calls = []
        def run(group, output):
            calls.append((group, output.name))
            status = statuses[len(calls) - 1]
            report = self.group_report(group, status)
            if mutation is not None:
                mutation(group, report)
            output.write_text(json.dumps(report), encoding="utf-8")
            return status
        return CORPUS._collect_groups(run, self.work / "reports"), calls

    def test_collector_requires_both_successes_and_preserves_original_reports(self):
        status, calls = self.collect((0, 0))
        self.assertEqual(0, status)
        self.assertEqual([("c", "corpus-c.json"), ("cpp", "corpus-cpp.json")], calls)
        for group in CORPUS.GROUPS:
            report = json.loads((self.work / "reports" / ("corpus-" + group + ".json")).read_text(encoding="utf-8"))
            self.assertTrue(report["success"])
            self.assertEqual(list(CORPUS.GROUPS[group]), [item["libraryId"] for item in report["libraries"]])

    def test_collector_collects_snapshot_only_failures_but_never_returns_success(self):
        for statuses in ((3, 0), (0, 3), (3, 3)):
            with self.subTest(statuses=statuses):
                status, calls = self.collect(statuses)
                self.assertEqual(3, status)
                self.assertEqual(["c", "cpp"], [group for group, _ in calls])

    def test_collector_stops_on_a_c_hard_error(self):
        for hard_error in (1, 2):
            with self.subTest(hard_error=hard_error):
                status, calls = self.collect((hard_error, 0))
                self.assertEqual(hard_error, status)
                self.assertEqual(["c"], [group for group, _ in calls])

    def test_collector_cannot_hide_cpp_execution_failure_after_unreviewed_c(self):
        status, calls = self.collect((3, 1))
        self.assertEqual(1, status)
        self.assertEqual(["c", "cpp"], [group for group, _ in calls])

    def test_collector_rejects_misclassified_or_incomplete_unreviewed_reports(self):
        def wrong_group(report): report["group"] = "cpp"
        def wrong_platform(report): report["platform"] = "not-this-host"
        def missing_library(report): report["libraries"].pop()
        def duplicate_library(report): report["libraries"][-1] = report["libraries"][0]
        def foreign_library(report): report["libraries"][0]["libraryId"] = "bimg"
        def failed_compilation(report): report["libraries"][0]["managedCompiled"] = False
        def failed_generation(report): report["libraries"][0]["generated"] = False
        def hidden_failure(report): report["libraries"][0]["failure"] = "compiler failed"
        def wrong_lock(report): report["corpusLockSha256"] = "0" * 64
        def mutated_inputs(report): report["repositoriesAfter"][0]["revision"] = "0" * 40
        def wrong_inputs(report): report["repositories"][0]["checkedOutContentSha256"] = "0" * 64
        def wrong_policy(report): report["selectedApiPolicy"]["policySha256"] = "0" * 64
        def wrong_failure_kind(report): report["failureKind"] = "execution"
        def false_success(report): report["success"] = True
        def missing_identity(report): del report["executionIdentity"]
        for mutate in (wrong_group, wrong_platform, missing_library, duplicate_library, foreign_library, failed_compilation,
                       failed_generation, hidden_failure, wrong_lock, mutated_inputs, wrong_inputs, wrong_policy,
                       wrong_failure_kind, false_success, missing_identity):
            with self.subTest(fault=mutate.__name__):
                status, calls = self.collect((3, 0), lambda group, report: mutate(report) if group == "c" else None)
                self.assertEqual(1, status)
                self.assertEqual(["c"], [group for group, _ in calls])

    def test_collector_requires_a_fresh_report_instead_of_reusing_a_previous_exit3(self):
        output = self.work / "reports"
        output.mkdir()
        (output / "corpus-c.json").write_text(json.dumps(self.group_report("c", 3)), encoding="utf-8")
        calls = []
        self.assertEqual(1, CORPUS._collect_groups(lambda group, path: calls.append(group) or 3, output))
        self.assertEqual(["c"], calls)

    def test_collector_rejects_mixed_source_or_generator_closures_and_cpp_syntax_failures(self):
        for fault in ("source", "generator", "syntax"):
            def mutate(group, report):
                if group != "cpp": return
                if fault == "syntax": del report["libraries"][0]["nativeBridgeSyntax"]
                else: report["executionIdentity"]["checkedOutSourceSha256" if fault == "source" else "executionClosureSha256"] = "d" * 64
            with self.subTest(fault=fault):
                status, calls = self.collect((3, 0), mutate)
                self.assertEqual(1, status)
                self.assertEqual(["c", "cpp"], [group for group, _ in calls])

    def test_collection_mode_forwards_unchanged_group_arguments_without_running_consumers(self):
        main = CORPUS.main
        def collect(run_group, output):
            self.assertEqual(ROOT / "artifacts/acceptance", output)
            for group in CORPUS.GROUPS:
                self.assertEqual(0, run_group(group, output / ("corpus-" + group + ".json")))
            return 3
        with patch.object(CORPUS, "main", return_value=0) as child, patch.object(CORPUS, "_collect_groups", side_effect=collect):
            self.assertEqual(3, main(["--dotnet", "locked-dotnet", "--configuration", "Release", "--collect-groups",
                "--corpus-root", "exact-corpus", "--tool-path", "closed-tool", "--runtime-path", "closed-runtime"]))
        self.assertEqual(["c", "cpp"], [call.args[0][call.args[0].index("--group") + 1] for call in child.call_args_list])
        for call in child.call_args_list:
            args = call.args[0]
            self.assertNotIn("--collect-groups", args)
            for option, expected in (("--dotnet", "locked-dotnet"), ("--configuration", "Release"),
                                     ("--corpus-root", "exact-corpus"), ("--tool-path", "closed-tool"), ("--runtime-path", "closed-runtime")):
                self.assertEqual(expected, args[args.index(option) + 1])

    def policy_fixture(self):
        root = self.work / "policy"
        configs = root / "tests/corpus"
        configs.mkdir(parents=True)
        for config in (ROOT / "tests/corpus").glob("*.bindgen.json"):
            shutil.copyfile(config, configs / config.name)
        policy = json.loads((ROOT / "tests/corpus/upstream-limitations.json").read_text(encoding="utf-8"))
        corpus = root / "upstream"
        observations = [item for library in policy["libraries"].values()
                        for kind in ("upstreamLimitations", "compilerConditionalHelpers") for item in library.get(kind, [])]
        headers = {}
        for limitation in observations:
            header = corpus / limitation["repository"] / limitation["header"]
            lines = headers.setdefault(header, [])
            lines.extend([""] * max(0, limitation["lastLine"] - len(lines)))
            body = limitation["declaration"].splitlines()
            self.assertEqual(limitation["lastLine"] - limitation["line"] + 1, len(body))
            lines[limitation["line"] - 1:limitation["lastLine"]] = body
        for header, lines in headers.items():
            header.parent.mkdir(parents=True)
            header.write_text("\n".join(lines) + "\n", encoding="utf-8")
        for limitation in observations:
            limitation["headerSha256"] = digest(corpus / limitation["repository"] / limitation["header"])
        (configs / "upstream-limitations.json").write_text(json.dumps(policy), encoding="utf-8")
        lock = {"repositories": list({item["repository"]: {"id": item["repository"], "revision": item["revision"]} for item in observations}.values())}
        limitation, = policy["libraries"]["bimg"]["upstreamLimitations"]
        header = corpus / limitation["repository"] / limitation["header"]
        return root, corpus, lock, header

    def test_selection_policy_producer_has_equal_lf_and_crlf_identity_without_rewriting_inputs(self):
        root, corpus, lock, _ = self.policy_fixture()
        path = root / "tests/corpus/upstream-limitations.json"
        value = json.loads(path.read_text(encoding="utf-8"))
        lf = (json.dumps(value, indent=2) + "\n").encode("utf-8")
        crlf = lf.replace(b"\n", b"\r\n")
        self.assertNotEqual(hashlib.sha256(lf).hexdigest(), hashlib.sha256(crlf).hexdigest())
        path.write_bytes(lf)
        first = selection_policy(root, lock, corpus)
        self.assertEqual(lf, path.read_bytes())
        path.write_bytes(crlf)
        second = selection_policy(root, lock, corpus)
        self.assertEqual(crlf, path.read_bytes())
        self.assertEqual(first, second)
        self.assertEqual(hashlib.sha256(lf).hexdigest(), second["policySha256"])

    def test_selection_policy_semantic_change_still_changes_its_identity(self):
        root, corpus, lock, _ = self.policy_fixture()
        first = selection_policy(root, lock, corpus)
        path = root / "tests/corpus/upstream-limitations.json"
        value = json.loads(path.read_text(encoding="utf-8"))
        value["libraries"]["miniaudio"]["reason"] += " Additional reviewed source rationale."
        path.write_bytes((json.dumps(value, indent=2) + "\n").encode("utf-8"))
        second = selection_policy(root, lock, corpus)
        self.assertNotEqual(first["policySha256"], second["policySha256"])
        self.assertNotEqual(first["libraries"], second["libraries"])
        self.assertEqual(first["libraries"]["miniaudio"]["excludedDeclarations"],
                         second["libraries"]["miniaudio"]["excludedDeclarations"])

    def test_compiler_only_helper_keeps_its_exact_branch_and_portable_operation(self):
        root, corpus, lock, _ = self.policy_fixture()
        selection_policy(root, lock, corpus)
        policy_path = root / "tests/corpus/upstream-limitations.json"
        policy = json.loads(policy_path.read_text(encoding="utf-8"))
        proof = policy["libraries"]["sdl3"]["compilerConditionalHelpers"][0]
        proof["declaration"] = proof["declaration"].replace("#if SDL_HAS_BUILTIN", "#if FAKE_HAS_BUILTIN")
        policy_path.write_text(json.dumps(policy), encoding="utf-8")
        with self.assertRaisesRegex(RuntimeError, "exact declaration or signature changed"):
            selection_policy(root, lock, corpus)

    def test_portable_public_operation_cannot_be_added_to_helper_exclusions(self):
        root, corpus, lock, _ = self.policy_fixture()
        policy_path = root / "tests/corpus/upstream-limitations.json"
        policy = json.loads(policy_path.read_text(encoding="utf-8"))
        portable = policy["libraries"]["sdl3"]["compilerConditionalHelpers"][0]["portableCounterpart"]
        policy["libraries"]["sdl3"]["excludedDeclarations"].append(portable)
        policy_path.write_text(json.dumps(policy), encoding="utf-8")
        config_path = root / "tests/corpus/sdl3.bindgen.json"
        config = json.loads(config_path.read_text(encoding="utf-8"))
        config["source"]["selection"]["excludeDeclarations"].append(portable)
        config_path.write_text(json.dumps(config), encoding="utf-8")
        with self.assertRaisesRegex(RuntimeError, "preserve its portable public operation"):
            selection_policy(root, lock, corpus)

    def test_unreviewed_broadening_of_one_overload_exclusion_fails(self):
        root, corpus, lock, _ = self.policy_fixture()
        selection_policy(root, lock, corpus)
        path = root / "tests/corpus/bimg.bindgen.json"
        config = json.loads(path.read_text(encoding="utf-8"))
        config["source"]["selection"]["excludeDeclarations"] = ["bimg::imageConvert"]
        path.write_text(json.dumps(config), encoding="utf-8")
        with self.assertRaisesRegex(RuntimeError, "without an audited exact policy update"):
            selection_policy(root, lock, corpus)

    def test_upstream_revision_drift_invalidates_an_old_limitation(self):
        root, corpus, lock, _ = self.policy_fixture()
        lock["repositories"][0]["revision"] = "0" * 40
        with self.assertRaisesRegex(RuntimeError, "reviewed source revision and bytes"):
            selection_policy(root, lock, corpus)

    def test_upstream_header_change_invalidates_an_old_limitation(self):
        root, corpus, lock, header = self.policy_fixture()
        header.write_text(header.read_text(encoding="utf-8") + "// upstream added its definition\n", encoding="utf-8")
        with self.assertRaisesRegex(RuntimeError, "reviewed source revision and bytes"):
            selection_policy(root, lock, corpus)


if __name__ == "__main__":
    unittest.main(verbosity=2)
